/** check if the item is actually affiliation invite todo; (not a regular filing item). */
isAffiliationInvitation (item): boolean {
  // check that affiliation invitation details are set
  return !!item.affiliationInvitationDetails
}

async authorizeAffiliationInvitation (isAuthorized: boolean, affiliationInvitationTodo: TodoItemIF) {
  const response = await AuthServices.authorizeAffiliationInvitation(
    this.getAuthApiUrl,
    affiliationInvitationTodo.affiliationInvitationDetails.id,
    isAuthorized
  ).catch(err => {
    // eslint-disable-line no-console
    console.log('failed the call for authorization of affiliation invitation', err)
    this.authorizeAffiliationInvitationErrorDialog = true
    return null
  })

def _check_authorization(identifier, filing_json: dict,
                             business: Business,
                             filing_id: int = None) -> Tuple[dict, int]:

  if (event?.affiliationInvites[0].businessIdentifier) {
    this.businessIdentifier = event?.affiliationInvites[0].businessIdentifier
  }

  try {
    const affiliationInvitationId = invitationId || event?.affiliationInvites[0].id
    await AffiliationInvitationService.updateInvitation(affiliationInvitationId)
    const contact = await BusinessService.getMaskedContacts(this.businessIdentifier)
    this.businessContactEmail = contact?.data?.email
    this.isAuthorizationEmailSentDialogVisible = true
  } catch (err) {
    this.showCreateAffiliationInvitationErrorDialog()
  }
}

get helpDialogBlurb (): string {
